// Validasi Status Code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Looping validasi tiap object dalam array data
pm.test("Validate each user in array has id, email, first_name", function () {
    var jsonData = pm.response.json();
    jsonData.data.forEach(function(user) {
        pm.expect(user).to.have.property('id');
        pm.expect(user).to.have.property('email');
        pm.expect(user).to.have.property('first_name');

        // Conditional (if-else) untuk field opsional (avatar)
        if (user.avatar) {
            pm.expect(user.avatar).to.be.a('string');
        } else {
            pm.expect(user.avatar).to.be.null;
        }
    });
});

